package com.bookeat.payment.controller;
import com.bookeat.common.response.*;import com.bookeat.security.AppPrincipal;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.access.prepost.PreAuthorize;import lombok.RequiredArgsConstructor;import io.swagger.v3.oas.annotations.Operation;import io.swagger.v3.oas.annotations.security.SecurityRequirement;import java.util.*;
@RestController @RequiredArgsConstructor @SecurityRequirement(name="bearerAuth")
public class PaymentController {
private final com.bookeat.payment.service.PaymentService service;private final com.bookeat.payment.service.PaymentTransactions transactions;private final com.bookeat.payment.mapper.PaymentMapper mapper;private final com.bookeat.payment.service.FinanceReadService reads;
 @PostMapping("/api/v1/customer/payments/create-order") @ResponseStatus(org.springframework.http.HttpStatus.CREATED) @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Create server-priced payment intent and gateway order",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.View> op0(@AuthenticationPrincipal AppPrincipal p,@RequestHeader("Idempotency-Key") String key,@Valid @RequestBody com.bookeat.payment.dto.PaymentRequests.Create q){return ApiResponse.ok("Create server-priced payment intent and gateway order",service.create(p.userId(),key,q));}
 @PostMapping("/api/v1/customer/payments/verify") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Verify signature and captured provider payment",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.View> op1(@AuthenticationPrincipal AppPrincipal p,@Valid @RequestBody com.bookeat.payment.dto.PaymentRequests.Verify q){return ApiResponse.ok("Verify signature and captured provider payment",service.verify(p.userId(),q));}
 @GetMapping("/api/v1/customer/payments") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="List own payments",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<PageResponse<com.bookeat.payment.dto.PaymentResponses.View>> op2(@AuthenticationPrincipal AppPrincipal p,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return ApiResponse.ok("List own payments",service.list(p.userId(),page,size));}
 @GetMapping("/api/v1/customer/payments/{id}") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Load own payment state",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.View> op3(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id){return ApiResponse.ok("Load own payment state",service.get(p.userId(),id));}
 @PutMapping("/api/v1/customer/payments/{id}/cancel-cash") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Cancel an unconfirmed cash payment intent",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.View> op4(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id,@Valid @RequestBody com.bookeat.payment.dto.PaymentRequests.Action q){return ApiResponse.ok("Cancel an unconfirmed cash payment intent",mapper.view(transactions.cancelOffline(p.userId(),id,q)));}
 @GetMapping("/api/v1/owner/restaurants/{restaurantId}/payments") @PreAuthorize("hasRole('OWNER') and hasAuthority('OWNER_PAYMENT_VIEW')") @Operation(summary="List owned restaurant payments",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<PageResponse<com.bookeat.payment.dto.PaymentResponses.View>> op5(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID restaurantId,@RequestParam(defaultValue="0") @Min(0) int page,@RequestParam(defaultValue="20") @Min(1) @Max(100) int size){return ApiResponse.ok("List owned restaurant payments",reads.payments(p.userId(),restaurantId,page,size));}
 @PutMapping("/api/v1/owner/restaurants/{restaurantId}/payments/{id}/confirm-cash") @PreAuthorize("hasRole('OWNER') and hasAuthority('OWNER_PAYMENT_MANAGE')") @Operation(summary="Confirm cash actually received from customer",description="Authenticated and scoped to the requesting role; validates ownership, state and versions. See PHASE9_15_API.md for request prerequisites and errors.")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.View> op6(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID restaurantId,@PathVariable UUID id,@Valid @RequestBody com.bookeat.payment.dto.PaymentRequests.Action q){return ApiResponse.ok("Confirm cash actually received from customer",service.cash(p.userId(),restaurantId,id,q));}
 @PostMapping("/api/v1/customer/payments/{id}/refresh") @PreAuthorize("hasRole('CUSTOMER')") @Operation(summary="Refresh own Razorpay payment through authenticated session lookup")
 public ApiResponse<com.bookeat.payment.dto.PaymentResponses.View> refresh(@AuthenticationPrincipal AppPrincipal p,@PathVariable UUID id){return ApiResponse.ok("Payment refreshed",service.refresh(p.userId(),id));}
}
